import smtplib
from datetime import datetime, timedelta, timezone

MAX_LINES = 20


def add_event(event, queue=None):
    """Append the event to queue, or to a new list when none is given, and return it."""
    if queue is None:
        queue = []
    queue.append(event)
    return queue


def stamp(event):
    return event["at"].astimezone(timezone.utc).isoformat(timespec="minutes")


def render(events):
    lines = [f"{stamp(event)} {event['title']}" for event in events]
    return "\n".join(lines[:MAX_LINES])


def recent(events):
    """Events from the last day; each event's "at" is a timezone-aware datetime."""
    cutoff = datetime.now(timezone.utc) - timedelta(days=1)
    return [event for event in events if event["at"] >= cutoff]


def average_age_hours(events):
    """The mean age of the events, in hours."""
    now = datetime.now(timezone.utc)
    total = sum((now - event["at"]).total_seconds() for event in events)
    return total / len(events) / 3600


def send(host, sender, recipient, body):
    with smtplib.SMTP(host, timeout=10) as smtp:
        smtp.sendmail(sender, [recipient], body)
